// @ts-check
// Bindings for the Go App struct (app.go). Normally generated by `wails build`;
// kept by hand because generation runs a temp exe that some Windows policies block.

export function CancelPairing() { return window['go']['main']['App']['CancelPairing'](); }
export function Connect(arg1) { return window['go']['main']['App']['Connect'](arg1); }
export function Disconnect() { return window['go']['main']['App']['Disconnect'](); }
export function Discover() { return window['go']['main']['App']['Discover'](); }
export function FinishPairing(arg1) { return window['go']['main']['App']['FinishPairing'](arg1); }
export function LastHost() { return window['go']['main']['App']['LastHost'](); }
export function LaunchApp(arg1) { return window['go']['main']['App']['LaunchApp'](arg1); }
export function SendText(arg1) { return window['go']['main']['App']['SendText'](arg1); }
export function SetVolume(arg1) { return window['go']['main']['App']['SetVolume'](arg1); }
export function SendKey(arg1) { return window['go']['main']['App']['SendKey'](arg1); }
export function StartPairing(arg1) { return window['go']['main']['App']['StartPairing'](arg1); }
export function CloseToTray() { return window['go']['main']['App']['CloseToTray'](); }
export function QuitApp() { return window['go']['main']['App']['QuitApp'](); }
export function ResizeWindow(arg1, arg2, arg3, arg4) { return window['go']['main']['App']['ResizeWindow'](arg1, arg2, arg3, arg4); }
export function SetCloseToTray(arg1) { return window['go']['main']['App']['SetCloseToTray'](arg1); }
export function SetCompactMode(arg1) { return window['go']['main']['App']['SetCompactMode'](arg1); }
export function ShowWindow() { return window['go']['main']['App']['ShowWindow'](); }
export function ToggleFullscreen() { return window['go']['main']['App']['ToggleFullscreen'](); }
export function TrayAvailable() { return window['go']['main']['App']['TrayAvailable'](); }
